#include <vector>
#include <algorithm>

class Solution {
public:
    int minElevatorTrips(std::vector<int>& weights, int maxWeight) {
        int n = weights.size();
        std::vector<std::pair<int, int>> dp(1 << n, {n + 1, 0});
        dp[0] = {1, 0};
        for (int mask = 0; mask < (1 << n); ++mask) {
            auto [rides, curW] = dp[mask];
            for (int i = 0; i < n; ++i) {
                if (!(mask & (1 << i))) {
                    int nxtMask = mask | (1 << i);
                    int w = weights[i];
                    std::pair<int, int> cand = (curW + w <= maxWeight) ? std::make_pair(rides, curW + w) : std::make_pair(rides + 1, w);
                    if (cand < dp[nxtMask]) dp[nxtMask] = cand;
                }
            }
        }
        return dp[(1 << n) - 1].first;
    }
};

import java.util.*;

class Solution {
    public int minElevatorTrips(int[] weights, int maxWeight) {
        int n = weights.length;
        int[][] dp = new int[1 << n][2];
        for (int[] row : dp) Arrays.fill(row, n + 1);
        dp[0][0] = 1;
        dp[0][1] = 0;
        for (int mask = 0; mask < (1 << n); mask++) {
            int rides = dp[mask][0], curW = dp[mask][1];
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) == 0) {
                    int nxtMask = mask | (1 << i);
                    int w = weights[i];
                    int nextRides = (curW + w <= maxWeight) ? rides : rides + 1;
                    int nextW = (curW + w <= maxWeight) ? curW + w : w;
                    if (nextRides < dp[nxtMask][0] || (nextRides == dp[nxtMask][0] && nextW < dp[nxtMask][1])) {
                        dp[nxtMask][0] = nextRides;
                        dp[nxtMask][1] = nextW;
                    }
                }
            }
        }
        return dp[(1 << n) - 1][0];
    }
}

