                const nextW = (curW + w <= maxWeight) ? curW + w : w;
                if (nextRides < dpRides[nxtMask] || (nextRides === dpRides[nxtMask] && nextW < dpWeight[nxtMask])) {
                    dpRides[nxtMask] = nextRides;
                    dpWeight[nxtMask] = nextW;
                }
            }
        }
